{
  "status": "SUPPORTED",
  "task_summary": "Locate fastening tool and components, perform fastening, place tool on workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "implements the fastening action",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": [
          "screwdriver",
          "wrench",
          "clamp",
          "glue_gun"
        ],
        "required_properties": [
          "capable_of_fastening",
          "compatible_with_components"
        ]
      },
      {
        "id": "components",
        "entity_kind": "OBJECT",
        "function": "items to be joined",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": [
          "metal_pieces",
          "plastic_blocks",
          "wood_parts"
        ],
        "required_properties": [
          "compatible_with_each_other",
          "compatible_with_fastening_tool"
        ]
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "surface where task occurs and tool is left",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "tabletop",
          "workbench_surface"
        ],
        "required_properties": [
          "stable_surface"
        ]
      },
      {
        "id": "storage_units",
        "entity_kind": "REGION",
        "function": "containers potentially holding required items",
        "required_count": 2,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "drawer",
          "cabinet"
        ],
        "required_properties": [
          "openable",
          "accessible"
        ]
      }
    ],
    "functional_relations": [
      {
        "id": "relation_1",
        "relation": "fit",
        "participant_roles": [
          "components",
          "components"
        ],
        "required": true
      },
      {
        "id": "relation_2",
        "relation": "act_on",
        "participant_roles": [
          "fastening_tool",
          "components"
        ],
        "required": true
      },
      {
        "id": "relation_3",
        "relation": "end_up_at",
        "participant_roles": [
          "fastening_tool",
          "workbench"
        ],
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "operation_1",
        "operation": "locate_and_retrieve",
        "participant_roles": [
          "fastening_tool",
          "components",
          "storage_units"
        ],
        "operation_count": 1
      },
      {
        "id": "operation_2",
        "operation": "fasten",
        "participant_roles": [
          "fastening_tool",
          "components"
        ],
        "operation_count": 1
      },
      {
        "id": "operation_3",
        "operation": "place_tool",
        "participant_roles": [
          "fastening_tool",
          "workbench"
        ],
        "operation_count": 1
      }
    ]
  },
